const body = $('Schedule webhook').first().json.body;
const today = $now.setZone('Asia/Seoul').toFormat('yyyy-MM-dd');
const isDate = s => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s) && !isNaN(Date.parse(s + 'T00:00:00Z')) && new Date(s + 'T00:00:00Z').toISOString().slice(0, 10) === s;
const dayKo = s => '일월화수목금토'[new Date(s + 'T00:00:00Z').getUTCDay()];
const addDays = (s, n) => new Date(Date.parse(s + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10);
const daysBetween = (a, b) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
// LLM이 날짜를 지어내지 않았는지: 요청 문장에 날짜를 말하는 표현이 있어야 날짜를 믿는다
const mentionsDate = text => /\d{1,2}\s*월|\d{1,2}\s*일|\d{4}-\d{1,2}-\d{1,2}|\d{1,2}\/\d{1,2}|오늘|내일|모레|글피|요일|이번\s*주|다음\s*주|주말|월말|월초/.test(String(text ?? ''));
const range = (a, b) => (!b || a === b) ? `${a}(${dayKo(a)})` : `${a}(${dayKo(a)}) ~ ${b}(${dayKo(b)})`;
const won = n => Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',') + '원';
const hash = s => { let h = 5381; for (const c of s) h = ((h * 33) ^ c.codePointAt(0)) >>> 0; return h.toString(36).toUpperCase().slice(-4).padStart(4, '0'); };
const title = String(body.title).trim();
const user = String(body.user).trim();
const date = String(body.date).trim();
const endDate = String(body.end_date ?? '').trim() || date;
const reply = (route, answer, extra = {}) => [{ json: { route, answer, ...extra } }];
if (!isDate(date) || !isDate(endDate)) return reply('입력 필요', `날짜는 2026-11-06처럼 YYYY-MM-DD 모양으로 보내 주세요. (받은 값: ${date}${endDate !== date ? ' ~ ' + endDate : ''})`);
if (endDate < date) return reply('입력 필요', `끝 날짜(${endDate})가 시작 날짜(${date})보다 빠릅니다.`);
if (date < today) return reply('거절', `${range(date)}은 이미 지난 날짜라 등록하지 않았습니다. 오늘은 ${range(today)}입니다.`);

// 연습용 회사 달력 (shared = 모두가 볼 수 있는 일정)
const BASE = [
  { id: 'E-BASE-1', title: '주간 회의', date: '2026-10-23', end_date: '2026-10-23', owner: '박서연', shared: false },
  { id: 'E-BASE-2', title: '고객사 미팅', date: '2026-10-27', end_date: '2026-10-27', owner: '이준호', shared: false },
  { id: 'E-BASE-3', title: '신제품 발표', date: '2026-11-02', end_date: '2026-11-02', owner: '마케팅팀', shared: true },
  { id: 'E-BASE-4', title: '전사 워크숍', date: '2026-11-13', end_date: '2026-11-13', owner: '전사', shared: true },
];
let store = { events: [] };
try { store = $getWorkflowStaticData('global'); if (!Array.isArray(store.events)) store.events = []; } catch (error) { store = { events: [] }; }
const all = [...BASE, ...store.events];
const existing = all.find(e => e.title === title && e.date === date && e.end_date === endDate && e.owner === user);
const event = existing || { id: `E-${date.replace(/-/g, '')}-${hash(user + '|' + title + '|' + endDate)}`, title, date, end_date: endDate, owner: user, shared: false };
if (!existing) {
  store.events.push(event);
  if (store.events.length > 200) store.events.splice(0, store.events.length - 200);
}
// 남의 개인 일정은 보여 주지 않음: 내 일정 + 모두 보는 일정만
const conflicts = all.filter(e => e.id !== event.id && (e.owner === user || e.shared) && e.date <= endDate && e.end_date >= date)
  .map(e => ({ title: e.title, date: e.date, owner: e.owner }));
const warn = conflicts.length ? ` ⚠ 같은 기간 일정: ${conflicts.map(c => `${c.title}(${c.date}, ${c.owner})`).join(', ')}.` : '';
return reply('등록 완료', `${range(date, endDate)} '${title}' 일정을 ${existing ? '이미 등록해 두었습니다' : '등록했습니다'} (일정 번호 ${event.id}).${warn}`,
  { event: { id: event.id, title, date, end_date: endDate, owner: user }, conflicts });
